using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" → "$type".
            // Existing documents use "Discriminator", so we must preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|Key" → "Key".
            // Existing documents use "Blog|<key>", so we must opt in to the legacy format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: EF Core 9 removed HasIndex support for Cosmos.
            // Indexes are managed via Cosmos DB directly, not EF Core.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }
}

/// <summary>
/// Preserves the EF Core 8 "Discriminator|Key" id format for backward compatibility.
/// </summary>
class LegacyIdValueGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var key = entry.Property("Id").CurrentValue?.ToString() ?? Guid.NewGuid().ToString();
        return $"{entityType}|{key}";
    }
}

